{'source_statement_id': 'toda:tex:ch4:0005', 'source_text': '\begin{proposition}[]\label{prop:4.2}
% Prop4.2.\
次の列は完全列である：
\begin{equation}\label{4.4}
% (4.4)
\cdots \longrightarrow
\pit{i}{n}\ \xrightarrow{\ \Ex\ }\ \pit{i+1}{n+1}\
\xrightarrow{\ H\ }\ \pit{i+1}{2n+1}\
\xrightarrow{\ \Delta\ }\ \pit{i-1}{n}\
\xrightarrow{\ \Ex\ }\ \pit{i}{n+1}\ \xrightarrow{\ H\ }\ \cdots.
\end{equation}
\end{proposition}', 'source_sha256': 'e61e29d9d69449ab52cb12395945cb96f11a7071379dd3cd9f5c8b075a03de56', 'source_chapter': 4, 'source_position': 6800, 'proof_eligible': False}

{'source_statement_id': 'toda:tex:ch4:0008', 'source_text': '\begin{equation}\label{4.6}
% (4.6).\
\raisetag{3ex}
\begin{aligned}[t]
  &n\ge 1,\ p^r\alpha=0,\ p^s\gamma=0,\ r,s>0,\ 
  \alpha\in[E^n Y, Z],\ \gamma\in[EW, X] \ \text{のとき, }\\
  &\beta\in[X, Y]\ \text{に対して, } \ 
  p^r(\alpha\circ E^r\beta) = 0,\ p^s(\beta\circ\gamma) = 0 \ \text{である. }\\
  &\text{さらに, }\ \alpha\circ E^n\beta=0,\ \beta\circ\gamma = 0 \ \text{のとき, }
  p^{r+s}\todai[n]{\alpha, E^n\beta, E^n\gamma} = 0 \ \text{である. }\qquad
\end{aligned}
\end{equation}', 'source_sha256': '02893dbe2b6a29c9d0c22a8ff631c11260db22c705ce0f9d91a7f19e60148aef', 'source_chapter': 4, 'source_position': 7100, 'proof_eligible': False}

{'source_statement_id': 'toda:tex:ch4:0009', 'source_text': '\begin{equation}\label{4.7}
% (4.7).\
\raisetag{3ex}
\begin{aligned}[t]
  & n\ge1, \ \alpha\in\pis{k+n}{S^m; 2},\ \gamma\in\pis{i}{S^j; 2}
    \ \text{のとき, }\\
  & \alpha\circ E^n\pis{j}{S^k} = \alpha\circ E^n \pit{j}{k}
  \subset \pit{j+n}{m},
  \ \pis{j}{S^k}\circ\gamma = \pit{j}{k}\circ\gamma \subset\pit{i}{k}\ . \\
  &\text{さらに, }\ \alpha\circ E^n\beta=0,\ \beta\circ\gamma = 0 \ \text{のとき, }\\
  & \todai[n]{\alpha, E^n\beta, E^n\gamma}\ \text{は,}\
  \alpha\circ E^n\pit{i+1}{k} + \pit{j+n+1}{m}\circ E^{n+1}\gamma\
  \text{の coset で, }\qquad\qquad\qquad\\
  & \pit{i+n+1}{m} \ \text{の部分集合である. }
\end{aligned}
\end{equation}', 'source_sha256': 'f1182214b2859adb18e4076d004b068343a12a1019f4438465e3fc08f8cbfe76', 'source_chapter': 4, 'source_position': 7200, 'proof_eligible': False}

{'source_statement_id': 'toda:tex:ch4:0012', 'source_text': '\begin{equation}\label{4.8}
% (4.8).\
\raisetag{3ex}
\begin{aligned}[t]
& n \ \text{を偶数とする. } \\
& \Delta(\iota_{2n-1})=[\iota_{n-1},\iota_{n-1}]\ne0 \ \text{のとき, }\\
& \pit{2n-1}{n}
=E\,\pit{2n-2}{\,n-1}\ \oplus\ \Delta\,\pit{2n+1}{\,2n+1}
\cong E\,\pit{2n-2}{\,n-1}\ \oplus\ \mathbb{Z},\ \pit{2n}{\,n+1} = E^{2}\,\pit{2n-2}{\,n-1} 
\cong E\,\pit{2n-2}{\,n}.\\
& \Delta(\iota_{2n-1})=0 \ \text{のとき, }\\
& E^{2}:\pit{2n-2}{\,n-1}\to\pit{2n}{\,n+1}\ \text{は単射で, }\
\pit{2n}{\,n+1}/E^{2}\pit{2n-2}{\,n-1}\cong\mathbb{Z}_2 . \\
& \text{さらに,}\ \alpha\in\pit{2n-1}{n} \ \text{に対して, 次が成り立つ. }\\
& E\alpha\in E^{2}\pit{2n-2}{\,n-1} \ \Leftrightarrow \
H(\alpha)\in 2\,\pit{2n-1}{\,2n-1}\ .
\end{aligned}
\end{equation}', 'source_sha256': '4d3e6d8570a424afe52d49bf493427ed44471ca2618b4fb65f8ffaf93e3e1117', 'source_chapter': 4, 'source_position': 7500, 'proof_eligible': False}

